import { t as HashManager } from "../hash-JWH1eSsi.js";
import { Scrypt } from "../src/drivers/scrypt.js";
//#region factories/hash_manager.ts
/**
* Hash manager factory is used to create an instance of hash manager
* for testing
*/
var HashManagerFactory = class HashManagerFactory {
	/**
	* Config accepted by hash manager
	*/
	#config;
	constructor(config) {
		this.#config = config || {
			default: "scrypt",
			list: { scrypt: () => new Scrypt({}) }
		};
	}
	/**
	* Merge factory parameters
	*/
	merge(config) {
		return new HashManagerFactory(config);
	}
	/**
	* Create hash manager instance
	*/
	create() {
		return new HashManager(this.#config);
	}
};
//#endregion
export { HashManagerFactory };
